let lang='uk';
export function detectLang(saved){if(S[saved])return saved;for(const l of (typeof navigator!=='undefined'&&navigator.languages)||[]){const c=String(l).slice(0,2).toLowerCase();if(S[c])return c;}return 'uk';}
export function setLang(l){lang=S[l]?l:'uk';if(typeof document!=='undefined'&&document.documentElement)document.documentElement.lang=lang;return lang;}
export function getLang(){return lang;}
export function t(key,params){let s=S[lang][key]??S.en[key]??S.uk[key]??key;if(params)s=s.replace(/\{(\w+)\}/g,(m,k)=>params[k]??m);return s;}
export function missingKeys(){const base=Object.keys(S.uk),out={};for(const l of Object.keys(S)){const miss=base.filter(k=>!(k in S[l]));if(miss.length)out[l]=miss;}return out;}
